rect_source='''from collections import Counter, deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != background or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            component = []
            touches_edge = False
            while q:
                x, y = q.popleft()
                component.append((x, y))
                if x == 0 or x == h - 1 or y == 0 or y == w - 1:
                    touches_edge = True
                for dx in (-1, 0, 1):
                    for dy in (-1, 0, 1):
                        if dx == dy == 0:
                            continue
                        nx, ny = x + dx, y + dy
                        if 0 <= nx < h and 0 <= ny < w and grid[nx][ny] == background and (nx, ny) not in seen:
                            seen.add((nx, ny))
                            q.append((nx, ny))
            if not touches_edge:
                min_r = min(x for x, _ in component)
                max_r = max(x for x, _ in component)
                min_c = min(y for _, y in component)
                max_c = max(y for _, y in component)
                if len(component) == (max_r - min_r + 1) * (max_c - min_c + 1):
                    for x, y in component:
                        out[x][y] = 4
    return out
'''
